package com.example.takura.payments;
import static org.assertj.core.api.Assertions.*;import com.example.takura.payments.application.PaymentGateway;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;
class PaymentGatewayContractTest{private final Fake gateway=new Fake();@Test void redirectNeverMarksPayment(){String ref=gateway.createHostedPayment("quote-1");assertThat(gateway.fetchStatus(ref)).isEqualTo("PENDING");}@Test void forgedReplayAndMismatchNeverProducePaid(){assertThat(gateway.verifyNotification("tx-1|merchant-x|2500.00|ZAR".getBytes(),"bad")).isFalse();assertThat(gateway.verifyNotification("tx-1|merchant-demo|999.00|ZAR".getBytes(),"fixture-signature")).isFalse();assertThat(gateway.verifyNotification("tx-1|merchant-demo|2500.00|ZAR".getBytes(),"fixture-signature")).isTrue();assertThat(gateway.verifyNotification("tx-1|merchant-demo|2500.00|ZAR".getBytes(),"fixture-signature")).isFalse();}static final class Fake implements PaymentGateway{private final Set<String> events=new HashSet<>();public String createHostedPayment(String q){return "disabled-sandbox:"+q;}public boolean verifyNotification(byte[] body,String signature){String v=new String(body,StandardCharsets.UTF_8);String[] p=v.split("\\|");return "fixture-signature".equals(signature)&&p.length==4&&"merchant-demo".equals(p[1])&&"2500.00".equals(p[2])&&"ZAR".equals(p[3])&&events.add(p[0]);}public String fetchStatus(String r){return "PENDING";}public void refund(String r,String a,String c){throw new UnsupportedOperationException("Payments are disabled");}}}
